     1	import React from 'react';
     2	import { useIntl } from 'react-intl';
     3	import { Skeleton, VStack } from '@salesforce/retail-react-app/app/components/shared/ui';
     4	import Breadcrumb from '@salesforce/retail-react-app/app/components/breadcrumb';
     5	import PromoCallout from '@salesforce/retail-react-app/app/components/product-tile/promo-callout';
     6	
     7	/*
     8	 * `app/...`, not `@salesforce/retail-react-app/app/...`, for the two overridden modules below.
     9	 * pwa-kit-dev's OverridesResolverPlugin skips any request whose issuer already lives in
    10	 * `overrides/` (its `isFromExtends` guard), so a base-path import from this file would resolve
    11	 * to the *base* component even in the real app build — the same reason the page's own
    12	 * `product-view` import is relative. `Breadcrumb`, `PromoCallout` and `shared/ui` above have no
    13	 * override, so the base path is the correct one for them.
    14	 */
    15	import type { ProductViewHeaderProps } from 'app/components/product-view';
    16	import { ZimmProductContent } from 'app/components/ui-kits/molecules/zimmProductContent';
    17	import { selectPdpProductInfo } from '../productInfo';
    18	
    19	/**
    20	 * Replaces the title/price block of ProductView's header with the Zimmermann content group.
    21	 *
    22	 * The breadcrumb and promo callout are reproduced from the base header rather than dropped:
    23	 * `renderHeader` replaces the whole header block, and neither of those belongs to SFCC-89
    24	 * (breadcrumb is SFCC-578, badges are SFCC-132/225), so losing them here would be a
    25	 * regression rather than a scope decision.
    26	 *
    27	 * ProductView renders this once per breakpoint, so it stays free of side effects.
    28	 *
    29	 * A component rather than the bare render function it was on the page, so that it can hold
    30	 * `useIntl()` itself — `formatPrice` needs `formatNumber`. components.md exempts `useIntl` from
    31	 * the container/presentational rule because it reads a Provider mounted above the route tree,
    32	 * and this keeps the prop surface exactly `ProductViewHeaderProps`, which passing `formatPrice`
    33	 * in would have widened. `useIntl()` throws without an `IntlProvider`, so anything rendering
    34	 * this must supply one: the app does in the base `_app`, `.storybook/preview.tsx` does for the
    35	 * stories.
    36	 */
    37	export const StaticProductHeader = ({
    38	  name,
    39	  product: headerProduct,
    40	  priceData,
    41	  currency,
    42	  category: headerCategory,
    43	  isProductPartOfBundle,
    44	}: ProductViewHeaderProps) => {
    45	  // react-intl returns already-bound methods, so destructuring them cannot unbind anything —
    46	  // the rule cannot see that. Same suppression, and same reason, as the page's own `useIntl`.
    47	  // eslint-disable-next-line @typescript-eslint/unbound-method
    48	  const { formatNumber } = useIntl();
    49	
    50	  // The page keeps its own copy of this for the meta block it renders below the accordions,
    51	  // which is outside this header — so that one is not a leftover of this extraction.
    52	  const formatPrice = (amount: number, priceCurrency: string) =>
    53	    formatNumber(amount, { style: 'currency', currency: priceCurrency });
    54	
    55	  const info = selectPdpProductInfo(headerProduct ?? { name }, priceData, currency ?? '', formatPrice);
    56	
    57	  return (
    58	    <VStack mr={4} spacing={2} align="flex-start" marginBottom={[4, 4, 4, 0, 0]}>
    59	      {headerCategory && (
    60	        <Skeleton isLoaded={headerCategory} minWidth={64}>
    61	          <Breadcrumb categories={headerCategory} />
    62	        </Skeleton>
    63	      )}
    64	
    65	      {/*
    66	       * `minHeight` reserves the name's line box, so the title does not shove the page down
    67	       * when it resolves. SFCC's `Skeleton` baseStyle sets only `borderRadius` and `opacity`,
    68	       * so an empty one measures 0px; the base header avoids that by interpolating the name
    69	       * into a template, which stringifies `undefined` to "undefined" and is therefore always
    70	       * title-height. The value is the name's own line-height: `ZimmProductName` renders at
    71	       * `textStyle: 'heading3'` (declared in its recipe, not as a prop), whose `lineHeight` is
    72	       * `lineHeights['2xs']` (1.125rem / 18px) —
    73	       * the same entry `--zimm-font-lineheight-2xs` is derived from.
    74	       *
    75	       * This reserves ONE line, matching base. A name that wraps still shifts by ~18px, and
    76	       * wrapping is a real case — the design caps the name at 180px inside a 218px column and
    77	       * `zimmProductName/index.stories.tsx` ships a story for it. Reserving two lines would
    78	       * over-reserve for every single-line product and exceed base's own behaviour, which
    79	       * AGENTS.md's minimal-changes rule rules out.
    80	       */}
    81	      <Skeleton isLoaded={Boolean(info)} minHeight="var(--zimm-font-lineheight-2xs)">
    82	        {info && (
    83	          // h2, not h1: the page already emits a screen-reader-only
    84	          // <h1>Product Details</h1>, and the base header this replaces rendered the name
    85	          // as an h2. Changing the outline is SEO's call, not a side-effect of this ticket.
    86	          <ZimmProductContent
    87	            name={info.name}
    88	            headingLevel="h2"
    89	            // The base header gates its price and its promo together behind the same
    90	            // `!isProductPartOfBundle` check. The promo is gated below; without this the
    91	            // price would be the one part of that header which stopped being gated.
    92	            price={isProductPartOfBundle ? undefined : info.price}
    93	            description={info.description}
    94	          />
    95	        )}
    96	      </Skeleton>
    97	
    98	      {!isProductPartOfBundle && (
    99	        <Skeleton isLoaded={Boolean(headerProduct)}>
   100	          {headerProduct?.productPromotions && <PromoCallout product={headerProduct} />}
   101	        </Skeleton>
   102	      )}
   103	    </VStack>
   104	  );
   105	};
=============== productInfo.ts ===============
     1	/**
     2	 * Maps a Commerce API product onto the props the PDP's static-information components take.
     3	 *
     4	 * Extracted from the page so the mapping is unit-testable on its own. Nothing else on the PDP
     5	 * ties an external field name to a rendered prop, and a mis-keyed field here does not fail
     6	 * loudly: it falls through to `undefined`, the component returns `null`, and the page renders
     7	 * a plausible-looking product with one line quietly missing. Neither a Storybook `play`
     8	 * (which supplies its own props) nor an axe run can see that.
     9	 */
    10	
    11	/*
    12	 * The Commerce SDK's `Product` type does not carry Zimmermann's `c_*` custom attributes, and
    13	 * `@salesforce/retail-react-app` ships no types at all. This is the narrow shape this mapping
    14	 * actually reads — everything optional, because every one of these fields can be absent on a
    15	 * real catalogue product.
    16	 */
    17	export type PdpSourceProduct = {
    18	  id?: string;
    19	  name?: string;
    20	  longDescription?: string;
    21	  /** Master product reference. Present on a variant; absent on a standard product. */
    22	  master?: { masterId?: string };
    23	  /** Zimmermann custom attribute holding the model's measurements and worn size. */
    24	  c_modelFit?: string;
    25	};
    26	
    27	/** The subset of `getPriceData`'s result this mapping needs. */
    28	export type PdpSourcePrice = { currentPrice?: number };
    29	
    30	/** Formats a bare amount for the storefront. Injected so this module stays free of react-intl. */
    31	export type FormatPrice = (amount: number, currency: string) => string;
    32	
    33	export type PdpProductInfo = {
    34	  name: string;
    35	  price: string;
    36	  description?: string;
    37	  modelInfo?: string;
    38	  styleCode?: string;
    39	};
    40	
    41	/**
    42	 * @param product - The resolved product (variant when one is selected, master otherwise).
    43	 * @param priceData - `getPriceData(...)`'s result, as ProductView computes it.
    44	 * @param currency - The storefront's active currency code.
    45	 * @param formatPrice - Currency formatter, normally `intl.formatNumber`.
    46	 * @returns Props for the static-information components, or `null` while the product loads.
    47	 */
    48	export const selectPdpProductInfo = (
    49	  product: PdpSourceProduct | undefined | null,
    50	  priceData: PdpSourcePrice | undefined | null,
    51	  currency: string,
    52	  formatPrice: FormatPrice,
    53	): PdpProductInfo | null => {
    54	  if (!product?.name) return null;
    55	
    56	  return {
    57	    name: product.name,
    58	    price: typeof priceData?.currentPrice === 'number' ? formatPrice(priceData.currentPrice, currency) : '',
    59	    description: product.longDescription,
    60	    modelInfo: product.c_modelFit,
    61	    // The style code shoppers see is the *master* style number. `product.id` is the variant
    62	    // SKU once a size is selected, so reading it would silently show a different value after
    63	    // the first swatch click. Standard products have no master, and there `id` is correct.
    64	    styleCode: product.master?.masterId ?? product.id,
    65	  };
    66	};
=============== richText.tsx ===============
     1	import React, { type ReactNode } from 'react';
     2	
     3	/**
     4	 * Renders SFCC-authored rich text (product description, model copy) as React elements.
     5	 *
     6	 * This deliberately does **not** sanitise a string and hand it to `dangerouslySetInnerHTML`.
     7	 * It parses the markup and emits React nodes, so raw HTML is never injected: every text run
     8	 * goes through React's own escaping and every attribute is discarded. The worst case for a
     9	 * malformed or hostile input is that it renders as visible text, not that it executes.
    10	 *
    11	 * Why not `isomorphic-dompurify` — the engine the earlier SFCC-89 attempt on PR #57 adds as a
    12	 * production dependency: importing it anywhere in the SSR graph crashes the server render.
    13	 * webpack bundles jsdom into the server bundle but rewrites `__dirname`, so jsdom's
    14	 * module-scope
    15	 * `fs.readFileSync(path.resolve(__dirname, '../../../browser/default-stylesheet.css'))`
    16	 * resolves outside the project and throws ENOENT at *import* time, before `sanitize()` is ever
    17	 * called. Reproduced on 2026-08-23: a PDP that returns 200 returns 500 with the import present,
    18	 * and the asset is never copied into `build/`, so a production bundle fails the same way. Needs
    19	 * raising with Integration before #57's dependency addition is accepted.
    20	 *
    21	 * Scope: the tag allow-list below covers what Business Manager actually authors today
    22	 * (`<br>`, `<ul>`, `<li>`, plus basic emphasis). Anything outside it is unwrapped — the tag is
    23	 * dropped, its text kept — except for the script-bearing elements, whose content is dropped
    24	 * too so their source does not surface as visible copy.
    25	 */
    26	
    27	/** Container and inline elements that are reproduced as real React elements. */
    28	const ALLOWED_TAGS = new Set(['p', 'ul', 'ol', 'li', 'strong', 'em', 'b', 'i']);
    29	
    30	/** Allow-listed elements that never have children. */
    31	const VOID_TAGS = new Set(['br']);
    32	
    33	/**
    34	 * Elements whose *content* is discarded along with the tag. Unwrapping these would turn
    35	 * script or style source into visible page copy. `iframe`/`object`/`embed` carry no text worth
    36	 * keeping either.
    37	 */
    38	const DROP_CONTENT_TAGS = new Set(['script', 'style', 'template', 'noscript', 'iframe', 'object', 'embed', 'svg']);
    39	
    40	/**
    41	 * The HTML void elements. These never have a closing tag, so one must not be treated as
    42	 * opening a region — `<embed src="y">z` would otherwise swallow `z` and everything after it.
    43	 */
    44	const VOID_ELEMENTS = new Set([
    45	  'area',
    46	  'base',
    47	  'br',
    48	  'col',
    49	  'embed',
    50	  'hr',
    51	  'img',
    52	  'input',
    53	  'link',
    54	  'meta',
    55	  'param',
    56	  'source',
    57	  'track',
    58	  'wbr',
    59	]);
    60	
    61	/** Elements that hold no text and must not leave a stray text node behind. */
    62	const LIST_CONTAINERS = new Set(['ul', 'ol']);
    63	
    64	/**
    65	 * Matches one tag. The alternation in the attribute group lets a quoted attribute value
    66	 * contain `>` (`<a title="a > b">`) without ending the match early.
    67	 */
    68	const TAG_RE = /<(\/?)([a-zA-Z][a-zA-Z0-9-]*)((?:[^>"']|"[^"]*"|'[^']*')*)>/g;
    69	
    70	const NAMED_ENTITIES: Record<string, string> = {
    71	  amp: '&',
    72	  lt: '<',
    73	  gt: '>',
    74	  quot: '"',
    75	  apos: "'",
    76	  nbsp: '\u00a0',
    77	  hellip: '…',
    78	  mdash: '—',
    79	  ndash: '–',
    80	  rsquo: '’',
    81	  lsquo: '‘',
    82	  rdquo: '”',
    83	  ldquo: '“',
    84	  deg: '°',
    85	};
    86	
    87	const ENTITY_RE = /&(#[Xx][0-9A-Fa-f]+|#\d+|[A-Za-z][A-Za-z0-9]*);/g;
    88	
    89	/**
    90	 * Decodes character references in a text run. Applied only to text, never to markup, so an
    91	 * authored `&lt;script&gt;` becomes the literal characters `<script>` and is rendered as text
    92	 * by React rather than re-entering the parser.
    93	 */
    94	export const decodeEntities = (text: string): string =>
    95	  text.replace(ENTITY_RE, (match, entity: string) => {
    96	    if (entity.startsWith('#')) {
    97	      const isHex = entity[1] === 'x' || entity[1] === 'X';
    98	      const codePoint = Number.parseInt(isHex ? entity.slice(2) : entity.slice(1), isHex ? 16 : 10);
    99	      // Reject non-characters and anything past the Unicode range rather than throwing.
   100	      if (!Number.isFinite(codePoint) || codePoint <= 0 || codePoint > 0x10ffff) return match;
   101	      return String.fromCodePoint(codePoint);
   102	    }
   103	    return NAMED_ENTITIES[entity.toLowerCase()] ?? match;
   104	  });
   105	
   106	type Frame = { tag: string | null; children: ReactNode[] };
   107	
   108	/**
   109	 * Converts an SFCC rich-text string into React nodes.
   110	 *
   111	 * @param html - Raw markup from the Commerce API. `undefined`, `null` and blank input all
   112	 *   return an empty array, so a caller can render `null` when there is nothing to show.
   113	 * @returns The parsed nodes, safe to render directly as children.
   114	 */
   115	export const parseRichText = (html?: string | null): ReactNode[] => {
   116	  if (!html) return [];
   117	
   118	  const root: Frame = { tag: null, children: [] };
   119	  const stack: Frame[] = [root];
   120	  const top = () => stack[stack.length - 1];
   121	
   122	  // Depth counter for a DROP_CONTENT_TAGS region, so nested same-name tags close correctly.
   123	  let dropTag: string | null = null;
   124	  let dropDepth = 0;
   125	
   126	  const pushText = (raw: string) => {
   127	    if (!raw) return;
   128	    // A list container may only hold <li>; whitespace between items would be an invalid text
   129	    // child. Text that is not whitespace is kept, so nothing authored is silently lost.
   130	    const parentTag = top().tag;
   131	    if (parentTag && LIST_CONTAINERS.has(parentTag) && !raw.trim()) return;
   132	    top().children.push(decodeEntities(raw));
   133	  };
   134	
   135	  let cursor = 0;
   136	  let match: RegExpExecArray | null;
   137	  TAG_RE.lastIndex = 0;
   138	
   139	  while ((match = TAG_RE.exec(html)) !== null) {
   140	    const [full, closing, rawName, attrs] = match;
   141	    const tag = rawName.toLowerCase();
   142	
   143	    if (dropDepth === 0) pushText(html.slice(cursor, match.index));
   144	    cursor = match.index + full.length;
   145	
   146	    if (dropDepth > 0) {
   147	      if (tag === dropTag) dropDepth += closing ? -1 : 1;
   148	      if (dropDepth === 0) dropTag = null;
   149	      continue;
   150	    }
   151	
   152	    if (DROP_CONTENT_TAGS.has(tag)) {
   153	      // A void element (`<embed>`) and a self-closing `<svg/>` both open and close in one
   154	      // token, so neither starts a region to skip.
   155	      if (!closing && !VOID_ELEMENTS.has(tag) && !attrs.trimEnd().endsWith('/')) {
   156	        dropTag = tag;
   157	        dropDepth = 1;
   158	      }
   159	      continue;
   160	    }
   161	
   162	    if (closing) {
   163	      if (!ALLOWED_TAGS.has(tag)) continue;
   164	      // Unwind to the matching frame, searching from the top down so a nested `<li>` closes the
   165	      // frame it opened rather than its same-named ancestor. `findIndex` scans from the root, so
   166	      // it returned the OUTERMOST match: `<ul><li>a<ul><li>b</li></ul>c</li></ul>` closed the
   167	      // inner `li`, the inner `ul` and the outer `li` on one `</li>`, and `c` escaped the list
   168	      // entirely. Both nested lists and nested emphasis are authorable in Business Manager.
   169	      //
   170	      // Not `findLastIndex`: `tsconfig.json` pins `lib` to ES2019 and that file is Tier 1.
   171	      //
   172	      // A stray `</li>` with no open `<li>` leaves the stack untouched rather than closing
   173	      // something it did not open — `depth` stays -1 and the guard below skips it.
   174	      let depth = -1;
   175	      for (let index = stack.length - 1; index > 0; index -= 1) {
   176	        if (stack[index].tag === tag) {
   177	          depth = index;
   178	          break;
   179	        }
   180	      }
   181	      if (depth <= 0) continue;
   182	      while (stack.length > depth) closeTop();
   183	      continue;
   184	    }
   185	
   186	    if (VOID_TAGS.has(tag)) {
   187	      top().children.push(React.createElement(tag, { key: `${tag}-${top().children.length}` }));
   188	      continue;
   189	    }
   190	
   191	    if (!ALLOWED_TAGS.has(tag)) continue; // unwrap: drop the tag, keep whatever it contains
   192	    if (attrs.trimEnd().endsWith('/')) continue; // self-closed container has no content
   193	    stack.push({ tag, children: [] });
   194	  }
   195	
   196	  if (dropDepth === 0) pushText(html.slice(cursor));
   197	
   198	  // Unclosed tags still render, with whatever content they collected.
   199	  while (stack.length > 1) closeTop();
   200	
   201	  return root.children;
   202	
   203	  function closeTop() {
   204	    const frame = stack.pop();
   205	    /* c8 ignore next -- guarded by the `stack.length > 1` conditions at every call site */
   206	    if (!frame?.tag) return;
   207	    const parent = top();
   208	    parent.children.push(
   209	      React.createElement(
   210	        frame.tag,
   211	        { key: `${frame.tag}-${parent.children.length}` },
   212	        frame.children.length ? frame.children : undefined,
   213	      ),
   214	    );
   215	  }
   216	};
   217	
   218	/**
   219	 * The visible text of a rich-text value, with all markup removed.
   220	 *
   221	 * Derived by walking the output of `parseRichText` rather than re-stripping the string, so the
   222	 * two can never disagree about what counts as content — a second implementation of the
   223	 * drop/unwrap rules would drift the first time one of them changed.
   224	 *
   225	 * Callers use this to decide whether there is anything to render at all: Business Manager can
   226	 * save a field as `<p></p>` or a bare `<br>`, which parses to real nodes but shows nothing, and
   227	 * rendering it would leave an empty box still contributing to the layout rhythm.
   228	 */
   229	export const richTextToPlainText = (html?: string | null): string => nodeText(parseRichText(html));
   230	
   231	const nodeText = (node: ReactNode): string => {
   232	  if (node === null || node === undefined || typeof node === 'boolean') return '';
   233	  if (typeof node === 'string' || typeof node === 'number') return String(node);
   234	  if (Array.isArray(node)) return node.map(nodeText).join('');
   235	  if (React.isValidElement(node)) return nodeText((node.props as { children?: ReactNode }).children);
   236	  /* c8 ignore next -- ReactNode also admits portals and iterables, which this parser never emits */
   237	  return '';
   238	};
   239	
   240	/** True when a rich-text value would render nothing visible. */
   241	export const isBlankRichText = (html?: string | null): boolean => richTextToPlainText(html).trim() === '';

