+// react-helmet 6.1.0 ships no types and @types/react-helmet is not installed (adding a
+// package needs Integration approval — see AGENTS.md Hard Rule #7). This declares the
+// surface overrides/ actually uses: <Helmet> with element children.
+declare module 'react-helmet' {
+  import type React from 'react';
+
+  interface HelmetProps {
+    children?: React.ReactNode;
+    defer?: boolean;
+    encodeSpecialCharacters?: boolean;
+    htmlAttributes?: Record<string, string>;
+    bodyAttributes?: Record<string, string>;
+    titleTemplate?: string;
+    defaultTitle?: string;
+  }
+
+  export const Helmet: React.ComponentType<HelmetProps>;
+  export default Helmet;
+}
+
+// Mirrors node_modules/@salesforce/pwa-kit-react-sdk/ssr/universal/errors.js. `status` is
+// optional on the constructor because callers derive it from an API response that may not
+// carry one — the base retail-react-app PDP passes a possibly-undefined status through.
+declare module '@salesforce/pwa-kit-react-sdk/ssr/universal/errors' {
+  export class HTTPError extends Error {
+    constructor(status?: number, message?: string);
+    status?: number;
+    toString(): string;
+  }
+
+  export class HTTPNotFound extends HTTPError {
+    constructor(message?: string);
+  }
+}
+
 // Catch-all for all other @salesforce/retail-react-app subpaths not declared above.
 declare module '@salesforce/retail-react-app/*';

